import {validateSettings,replay,append,undo,overs} from './engine.js';
import {listMatches,saveMatch} from './storage.js';
import {createAccountUI} from './account.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let matches=[],busy=false,noticeTimer,installPrompt,tab='scorecard',selectedInnings=null;
let language='en',theme='light';try{language=localStorage.getItem('cricavo-language')||'en';theme=localStorage.getItem('cricavo-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light')}catch{}
document.documentElement.dataset.theme=theme;
const t=(en,si)=>language==='si'?si:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',bat:'m5 17 9-12 5 4-10 12z M4 18l-2 3',cup:'M8 3h8v7a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 14v6 M8 21h8',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-3a4 4 0 0 0-3-4',plus:'M12 5v14 M5 12h14',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M19 5l-1 1 M6 18l-1 1',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',undo:'M4 10h10a6 6 0 0 1 0 12 M4 10l5-5 M4 10l5 5',shield:'m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7z M8 12l3 3 5-6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h.01',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.bat}"/></svg>`;
const button=(label,action,cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${action==='account'?'aria-label="Account"':''}>${ico?icon(ico):''}${label}</button>`;
const team=(s,key)=>key==='A'?s.teamA:s.teamB;
const initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
function toast(text){clearTimeout(noticeTimer);document.querySelector('#toast').textContent=text;noticeTimer=setTimeout(()=>document.querySelector('#toast').textContent='',5500)}
function route(){const [page,id]=location.hash.slice(1).split('/');return {page:page||'home',id}}
function current(){return matches.find(m=>m.id===route().id)}
function link(page){location.hash=page}
const navItems=[['home','home','Overview','මුල් පිටුව'],['matches','bat','Matches','තරග'],['tournaments','cup','Tournaments','තරගාවලි'],['players','users','Players','ක්‍රීඩකයන්']];
function shell(content){const p=route().page;document.documentElement.lang=language;return `<aside class="sidebar"><a class="brand" href="#home"><img src="./icon.svg" alt=""><div>Cricavo<small>Every ball counts.</small></div></a><div class="side-label">${t('YOUR WORKSPACE','ඔබේ වැඩබිම')}</div><nav class="side-nav">${navItems.map(([id,ic,en,si])=>`<a class="nav-item ${p===id||(id==='matches'&&['new','score','live'].includes(p))?'active':''}" href="#${id}">${icon(ic)}${t(en,si)}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-label">${icon('shield')} ${t('Device workspace','මෙම උපාංගයේ වැඩබිම')}<br><span class="small">${t('Your matches stay on this browser.','ඔබේ තරග මෙම browser එකේ සුරැකේ.')}</span></div>${button(t('Install Cricavo','Cricavo ස්ථාපනය'),'install','ghost','download')}<span class="small muted">Cricavo · Early access 0.2</span></div></aside><div class="shell"><header class="topbar"><a class="brand" href="#home"><img src="./icon.svg" alt="">Cricavo</a><span class="muted small">${t('Your ground. Your game. Your story.','ඔබේ පිටිය. ඔබේ තරගය. ඔබේ කතාව.')}</span><div class="top-actions">${button(language==='en'?'සිංහල':'EN','language','ghost')}${button(`<span class="sr-label">${theme==='dark'?t('Light','Light'):t('Dark','Dark')}</span>`,'theme','ghost','sun')}${button(`<span class="account-text">${t('Account','ගිණුම')}</span>`,'account','','users')}</div></header><main class="content" id="main">${content}</main></div><nav class="mobile-nav" aria-label="${t('Main navigation','ප්‍රධාන මෙනුව')}">${navItems.map(([id,ic,en,si])=>`<a href="#${id}" class="${p===id||(id==='matches'&&['new','score','live'].includes(p))?'active':''}">${icon(ic)}${t(en,si)}</a>`).join('')}</nav>`}
function resultText(m,state){const r=state.result;if(!r)return '';return r.by==='tie'?t('Match tied','තරගය සමයි'):`${team(m.settings,r.winner)} ${t('won by','ජය ගත්තා ·')} ${r.margin} ${r.by==='runs'?t('runs','ලකුණු'):t('wickets','කඩුලු')}`}
function matchCard(m){const state=replay(m),s=m.settings;return `<article class="card match-card"><div class="row between"><span class="badge ${state.finished?'neutral':''}">${state.finished?t('COMPLETED','අවසන්'):t('IN PROGRESS','පැවැත්වෙමින්')} ${m.demo?'· DEMO':''}</span><span class="small muted">${s.ballType==='softball'?t('Softball','සැහැල්ලු පන්දු'):t('Hardball','ලෙදර් පන්දු')} · ${s.overs} ${t('overs','ඕවර')}</span></div>${['A','B'].map(key=>{const i=state.innings.find(x=>x.team===key);return `<div class="team-row"><div class="team-name"><span class="team-avatar">${esc(initials(team(s,key)))}</span><span>${esc(team(s,key))}</span></div><span class="score">${i?`${i.total}<span class="muted small"> / ${i.wickets} (${overs(i.balls,s.ballsPerOver)})</span>`:'<span class="small muted">'+t('Yet to bat','තවම ක්‍රීඩා කර නැත')+'</span>'}</span></div>`}).join('')}<div class="match-foot"><span>${state.finished?esc(resultText(m,state)):t('Saved on this device','මෙම උපාංගයේ සුරැකී ඇත')}</span><a href="#${state.finished?'live':'score'}/${m.id}">${state.finished?t('Scorecard','ලකුණු පුවරුව'):t('Resume scoring','ලකුණු සටහන් කරන්න')} →</a></div></article>`}
function home(){const active=matches.filter(m=>!replay(m).finished),completed=matches.length-active.length;return `<div class="page-head"><div><span class="eyebrow">${t('MATCH DAY STARTS HERE','තරග දිනය මෙතැනින්')}</span><h1>${t('Welcome to your crease.','ඔබේ ක්‍රිකට් ලෝකයට සාදරයෙන්.')}</h1><p class="muted">${t('A little less paperwork. A lot more cricket.','ලකුණු සටහන් කිරීම පහසුවෙන්. ක්‍රිකට් සඳහා වැඩි කාලයක්.')}</p></div></div><section class="card hero"><div><span class="eyebrow">${t('EVERY BALL COUNTS','සෑම පන්දුවක්ම වටිනවා')}</span><h2>${t('Big moments.<br>Small grounds.','පුංචි පිටියකත්<br>ලොකු ජයග්‍රහණ.')}</h2><p>${t('From a weekend softball game to your next club match. Set up, score, and keep the story.','සති අන්ත සැහැල්ලු පන්දු තරගයේ සිට සමාජ තරගය දක්වා. තරගය සකසා ලකුණු සුරකින්න.')}</p><a href="#new" class="btn">${icon('plus')}${t('Start a match','තරගයක් අරඹන්න')}</a></div><div class="pitch-art" aria-hidden="true"></div></section><div class="metrics">${[[matches.length,'Matches','තරග'],[active.length,'In progress','පැවැත්වෙමින්'],[completed,'Completed','අවසන්']].map(([v,en,si])=>`<div class="card metric"><span class="small muted">${t(en,si)}</span><strong>${v.toString().padStart(2,'0')}</strong></div>`).join('')}</div><div class="home-grid"><section><div class="section-head"><h2>${t('Your matches','ඔබේ තරග')}</h2><a class="small muted" href="#matches">${t('View all','සියල්ල')} →</a></div>${matches.length?matches.slice(0,3).map(matchCard).join(''):`<div class="card empty">${icon('bat')}<h3>${t('Your first innings awaits','ඔබේ පළමු ඉනිම අරඹන්න')}</h3><p>${t('No squad? No problem. Start with just three player names.','සංචිතයක් නැද්ද? ක්‍රීඩකයන් තිදෙනෙකුගේ නම් වලින් අරඹන්න.')}</p>${button(t('Explore a demo match','ආදර්ශ තරගයක් බලන්න'),'demo','')}</div>`}</section><aside class="stack"><div class="card"><span class="eyebrow">${t('BUILT FOR THE BOUNDARY','පිටියේදීම පහසුවෙන්')}</span><h3 class="spacer">${t('Less setup. More play.','පහසු සැකසුමක්. වැඩි ක්‍රීඩා කාලයක්.')}</h3>${[['1','Make it your match','ඔබට ගැළපෙන තරගයක්','Choose teams, overs and your local rules.','Teams, overs සහ ඔබේ නීති සකසන්න.'],['2','Score every ball','සෑම පන්දුවක්ම සටහන් කරන්න','Big buttons, automatic strike and instant scorecards.','ලොකු buttons, ස්වයංක්‍රීය strike සහ ලකුණු පුවරු.'],['3','Keep it with you','ඔබ ළඟම සුරකින්න','Device saving, offline access and backup export.','උපාංගයේ save කිරීම, offline සහ backup export.']].map(([n,en,si,desc,sd])=>`<div class="tip"><span class="step">${n}</span><div><h3>${t(en,si)}</h3><p>${t(desc,sd)}</p></div></div>`).join('')}</div><div class="notice">${icon('shield')}<span>${t('Early access: scoring works on this device. Cloud accounts and public live links are not connected yet.','මුල් අනුවාදය: scoring මෙම උපාංගයේ ක්‍රියාත්මකයි. Cloud ගිණුම් සහ පොදු live links තවම සම්බන්ධ නැහැ.')}</span></div></aside></div>`}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="80"':''} ${extra} required></label>`;
function newMatch(){return `<div class="page-head"><div><span class="eyebrow">${t('LET’S PLAY','ක්‍රීඩා කරමු')}</span><h1>${t('New match','අලුත් තරගයක්')}</h1><p class="muted">${t('A few details. Then you’re on the field.','විස්තර කිහිපයකින් තරගයට සූදානම්.')}</p></div><a class="btn ghost" href="#home">${icon('back')}${t('Back','ආපසු')}</a></div><form id="match-form"><div class="form-layout"><div class="stack"><section class="card form-section"><h3 class="step-label"><span class="step">1</span>${t('The match','තරගය')}</h3><span class="badge">${t('Quick setup · no squad needed','ඉක්මන් සැකසුම · සංචිතයක් අවශ්‍ය නැහැ')}</span><div class="fields">${field(t('Team A','කණ්ඩායම A'),'teamA','')}${field(t('Team B','කණ්ඩායම B'),'teamB','')}<label class="field">${t('Ball type','පන්දු වර්ගය')}<select name="ballType"><option value="softball">${t('Softball','සැහැල්ලු පන්දු')}</option><option value="hardball">${t('Hardball','ලෙදර් පන්දු')}</option></select></label>${field(t('Players per team','කණ්ඩායමක ක්‍රීඩකයන්'),'players',8,'number','min="2" max="22"')}<label class="field full">${t('Batting first · after the toss','පළමුව පහර දෙන්නේ · කාසියේ වාසිය අනුව')}<select name="battingFirst"><option value="A">${t('Team A','කණ්ඩායම A')}</option><option value="B">${t('Team B','කණ්ඩායම B')}</option></select></label></div></section><section class="card form-section"><h3 class="step-label"><span class="step">2</span>${t('Your playing rules','තරග නීති')}</h3><div class="fields">${field(t('Overs per innings','ඉනිමක ඕවර'),'overs',6,'number','min="1" max="50"')}${field(t('Balls per over','ඕවරයක පන්දු'),'ballsPerOver',6,'number','min="1" max="12"')}${field(t('Wide penalty','වයිඩ් දඬුවම් ලකුණු'),'widePenalty',1,'number','min="1" max="5"')}${field(t('No-ball penalty','නිපන්දු දඬුවම් ලකුණු'),'noBallPenalty',1,'number','min="1" max="5"')}</div><label class="check"><input type="checkbox" name="freeHit" checked>${t('Free hit after a no-ball','නිපන්දුවකට පසු free hit')}</label><label class="check"><input type="checkbox" name="wideCounts">${t('Wides count towards the over (custom rule)','වයිඩ් පන්දු ඕවරයට ගණන් කරන්න (විශේෂ නීතිය)')}</label><label class="check"><input type="checkbox" name="noBallCounts">${t('No-balls count towards the over (custom rule)','නිපන්දු ඕවරයට ගණන් කරන්න (විශේෂ නීතිය)')}</label><p class="small muted">${t('Rules lock when play starts. This build supports two limited-overs innings; super overs and revised targets follow later.','තරගය ඇරඹූ පසු නීති lock වේ. දැනට සීමිත ඕවර ඉනිම් දෙකක් ඇත; super over සහ revised target පසුව.')}</p></section><section class="card form-section"><h3 class="step-label"><span class="step">3</span>${t('Opening players','ආරම්භක ක්‍රීඩකයන්')}</h3><div class="fields">${field(t('Striker','පන්දුවට මුහුණ දෙන පිතිකරු'),'striker')}${field(t('Non-striker','අනෙක් පිතිකරු'),'nonStriker')}${field(t('Opening bowler','ආරම්භක පන්දු යවන්නා'),'bowler')}</div><p class="small muted">${t('Add new batters and bowlers as the match unfolds. Use initials when players share a name.','තරගය අතරතුර නව ක්‍රීඩකයන් එකතු කරන්න. එකම නම ඇති අයට initials භාවිත කරන්න.')}</p><p class="form-error" role="alert"></p><button class="btn primary" type="submit">${icon('bat')}${t('Start scoring','ලකුණු සටහන් කිරීම අරඹන්න')}</button></section></div><aside class="card sticky-note stack"><span class="eyebrow">${t('READY IN A MINUTE','විනාඩියකින් සූදානම්')}</span><h2>${t('Just bring your game.','ඔබේ තරගය රැගෙන එන්න.')}</h2><p class="muted">${t('You don’t need a full squad to start. Two batters and a bowler are enough.','ආරම්භයට සම්පූර්ණ සංචිතයක් අවශ්‍ය නැහැ. පිතිකරුවන් දෙදෙනෙක් සහ පන්දු යවන්නෙක් ප්‍රමාණවත්.')}</p><hr class="rule"><p class="small">${icon('shield')} ${t('Each ball is saved on this browser before the score updates.','ලකුණු යාවත්කාලීන කිරීමට පෙර සෑම පන්දුවක්ම browser එකේ save වේ.')}</p></aside></div></form>`}
function board(m,st,i=st.current){const s=m.settings,rate=i.balls?(i.total*s.ballsPerOver/i.balls).toFixed(2):'0.00';const target=st.innings.length>1&&i===st.innings[1]?st.innings[0].total+1:null;const ballsLeft=s.overs*s.ballsPerOver-i.balls;return `<section class="card scoreboard"><div class="row between"><span class="badge">${st.finished?t('FINAL','අවසන්'):i.complete?t('INNINGS BREAK','ඉනිම් විවේකය'):t('IN PLAY','ක්‍රීඩා කරමින්')}</span><span class="small muted">${s.ballType==='softball'?'SOFTBALL':'HARDBALL'} · ${i===st.innings[0]?t('1st innings','පළමු ඉනිම'):t('2nd innings','දෙවන ඉනිම')}</span></div><h3 class="spacer">${esc(team(s,i.team))}</h3><div class="big-score">${i.total} / ${i.wickets} <small>(${overs(i.balls,s.ballsPerOver)})</small></div><p class="muted small">${t('vs','එදිරිව')} ${esc(team(s,i.team==='A'?'B':'A'))}${i.freeHit&&!i.complete?' · FREE HIT':''}</p><div class="score-stats"><div><span>${t('RUN RATE','ලකුණු වේගය')}</span><strong>${rate}</strong></div><div><span>${t('OVERS','ඕවර')}</span><strong>${overs(i.balls,s.ballsPerOver)} / ${s.overs}</strong></div><div><span>${target?t('TARGET','ඉලක්කය'):t('EXTRAS','අතිරේක')}</span><strong>${target||Object.values(i.extras).reduce((a,b)=>a+b,0)}</strong></div></div>${target&&!i.complete?`<p class="small spacer">${t('Need','අවශ්‍යයි')} ${Math.max(0,target-i.total)} ${t('runs from','ලකුණු · පන්දු')} ${ballsLeft} ${t('balls','')}</p>`:''}</section>`}
function batsTable(i,all=false){const rows=Object.values(i.batters).filter(b=>all||[i.striker,i.nonStriker].includes(b.name));return `<div class="table-wrap"><table><thead><tr><th>${t('BATTER','පිතිකරු')}</th><th>R</th><th>B</th><th>4s</th><th>6s</th><th>SR</th></tr></thead><tbody>${rows.map(b=>`<tr><td><strong>${esc(b.name)} ${b.name===i.striker&&!i.complete?'*':''}</strong>${all?`<span class="player-status">${b.out?esc(b.dismissal):t('not out','නොදැවී')}</span>`:''}</td><td><strong>${b.runs}</strong></td><td>${b.balls}</td><td>${b.fours}</td><td>${b.sixes}</td><td>${b.balls?(b.runs/b.balls*100).toFixed(1):'—'}</td></tr>`).join('')}</tbody></table></div>`}
function bowlTable(i,s,all=false){return `<div class="table-wrap"><table><thead><tr><th>${t('BOWLER','පන්දු යවන්නා')}</th><th>O</th><th>R</th><th>W</th><th>ECO</th></tr></thead><tbody>${Object.values(i.bowlers).filter(b=>all||b.name===i.bowler).map(b=>`<tr><td><strong>${esc(b.name)}</strong></td><td>${overs(b.balls,s.ballsPerOver)}</td><td>${b.runs}</td><td>${b.wickets}</td><td>${b.balls?(b.runs*s.ballsPerOver/b.balls).toFixed(1):'—'}</td></tr>`).join('')}</tbody></table></div>`}
function scoring(m){const st=replay(m),i=st.current,s=m.settings,blocked=i.complete||i.needBatter||i.needBowler;return `<div class="page-head"><div><span class="eyebrow">${t('SCORING DESK','ලකුණු සටහන් කිරීම')}</span><h1>${esc(s.teamA)} <span class="muted small">vs</span> ${esc(s.teamB)}</h1><p class="small muted">${icon(navigator.onLine?'shield':'wifi')} ${t('Saved on this device ·','මෙම උපාංගයේ සුරැකී ඇත ·')} ${navigator.onLine?t('no cloud sync','cloud sync නැහැ'):t('offline','offline')} ${m.demo?' · DEMO':''}</p></div><a href="#live/${m.id}" class="btn">${icon('book')}${t('Scorecard','ලකුණු පුවරුව')}</a></div>${st.finished?`<div class="result-banner spacer">${esc(resultText(m,st))}</div>`:''}<div class="scoring-grid spacer"><div class="stack">${board(m,st)}<section class="card stack active-players">${batsTable(i)}${bowlTable(i,s)}<div class="row between"><span class="small muted">${t('RECENT DELIVERIES','මෑත පන්දු')}</span><span class="small muted">${t('Latest on the right','නවතම පන්දුව දකුණේ')}</span></div><div class="balls">${i.deliveries.slice(-12).map(e=>`<span class="ball ${e.wicket?'wicket':e.boundary?'boundary':''}">${e.label}</span>`).join('')||'<span class="muted small">'+t('Ready for the first ball','පළමු පන්දුවට සූදානම්')+'</span>'}</div></section><p class="small muted">${t('Primary scorer · Device workspace. Export a backup before clearing browser data.','ප්‍රධාන ලකුණු සටහන්කරු · browser data මකා දැමීමට පෙර backup එකක් ලබාගන්න.')}</p></div><div class="stack"><section class="card stack scoring-controls"><div class="row between"><h3>${t('Record delivery','පන්දුව සටහන් කරන්න')}</h3><span class="badge neutral">${t('BALL','පන්දුව')} ${i.balls%s.ballsPerOver+1}</span></div>${i.complete?`<div class="notice">${t('Innings complete.','ඉනිම අවසන්.')}</div>${!st.finished?button(t('Start second innings','දෙවන ඉනිම අරඹන්න'),'second','primary'):button(t('Export scorecard','ලකුණු පුවරුව export කරන්න'),'export','','download')}`:i.needBatter?`<p>${t('A new batter is needed.','නව පිතිකරුවෙකු තෝරන්න.')}</p>${button(t('Add next batter','ඊළඟ පිතිකරු'),'batter','primary','plus')}`:i.needBowler?`<p>${t('Over complete. Choose a different bowler.','ඕවරය අවසන්. වෙනත් පන්දු යවන්නෙකු තෝරන්න.')}</p>${button(t('Select next bowler','ඊළඟ පන්දු යවන්නා'),'bowler','primary')}`:''}<div class="scoring-keys">${[0,1,2,3,4,6].map(n=>`<button class="btn run-key ${n>=4?'boundary':''}" data-action="run-${n}" ${blocked?'disabled':''}>${n}</button>`).join('')}</div><div class="scoring-actions"><button class="btn" data-action="extras" ${blocked?'disabled':''}>${t('Extras','අතිරේක')}</button><button class="btn wicket" data-action="wicket" ${blocked?'disabled':''}>${t('Wicket','කඩුල්ල')}</button></div><hr class="rule">${button(t('Undo last action','අවසාන ක්‍රියාව ආපසු'),'undo','ghost','undo')}</section><section class="card stack"><h3>${t('Match tools','තරග මෙවලම්')}</h3>${button(t('Export backup','Backup ලබාගන්න'),'export','','download')}<p class="small muted">${t('Undo keeps an audit record. Earlier-ball corrections, interruptions and scorer handover arrive in later builds.','Undo සඳහා history එකක් තබයි. පෙර පන්දු සංස්කරණය, interruptions සහ scorer මාරු කිරීම ඉදිරි build වලදී.')}</p></section></div></div>`}
function live(m){const st=replay(m),i=st.innings[selectedInnings??st.innings.length-1]||st.current;return `<div class="page-head"><div><span class="eyebrow">${t('MATCH CENTRE','තරග මධ්‍යස්ථානය')}</span><h1>${esc(m.settings.teamA)} <span class="muted small">vs</span> ${esc(m.settings.teamB)}</h1><p class="small muted">${t('Device scorecard · public sharing not connected','මෙම උපාංගයේ ලකුණු පුවරුව · public sharing තවම නැහැ')}</p></div><a href="#score/${m.id}" class="btn">${icon('bat')}${t('Scoring desk','ලකුණු සටහන් කිරීම')}</a></div>${st.finished?`<div class="result-banner">${esc(resultText(m,st))}</div>`:''}<div class="scoring-grid spacer"><div class="stack">${board(m,st,i)}<div class="segment">${st.innings.map((x,n)=>`<button class="btn" data-action="innings-${n}" aria-pressed="${x===i}">${esc(team(m.settings,x.team))}</button>`).join('')}</div><section class="card"><div class="live-tabs">${[['scorecard','Scorecard','ලකුණු'],['history','Ball history','පන්දු ඉතිහාසය'],['info','Info','විස්තර']].map(([id,en,si])=>`<button data-action="tab-${id}" class="${tab===id?'active':''}">${t(en,si)}</button>`).join('')}</div>${tab==='scorecard'?`${batsTable(i,true)}<div class="small muted spacer">${t('Extras','අතිරේක')}: ${Object.values(i.extras).reduce((a,b)=>a+b,0)} (wd ${i.extras.wide}, nb ${i.extras.noBall}, b ${i.extras.bye}, lb ${i.extras.legBye})</div><h3 class="spacer">${t('Bowling','පන්දු යැවීම')}</h3>${bowlTable(i,m.settings,true)}`:tab==='history'?i.deliveries.slice().reverse().map(e=>`<div class="history-item"><span class="ball ${e.wicket?'wicket':e.boundary?'boundary':''}">${e.label}</span><div><div>${esc(e.bowler)} → ${esc(e.striker)}</div><span class="muted">${e.over} · ${t('Total','එකතුව')} ${e.score}${e.legal?'':' · '+t('extra delivery','අතිරේක පන්දුව')}</span></div></div>`).join('')||`<p class="muted">${t('No deliveries yet.','තවම පන්දු නැහැ.')}</p>`:`<div class="stack"><p>${m.settings.overs} ${t('overs','ඕවර')} · ${m.settings.ballsPerOver} ${t('balls per over','ඕවරයක පන්දු')}</p><p>${m.settings.players} ${t('players per team','කණ්ඩායමක ක්‍රීඩකයන්')} · ${m.settings.ballType}</p><p>${t('Batting first','මුලින් පහර දෙන්නේ')}: ${esc(team(m.settings,m.settings.battingFirst))}</p><p>${t('Free hit','Free hit')}: ${m.settings.freeHit?t('Enabled','සක්‍රිය'):t('Disabled','අක්‍රිය')}</p><p>${t('Undo history entries','Undo history සටහන්')}: ${m.audit?.length||0}</p><p class="muted small">${t('Last saved','අවසන් save')}: ${esc(new Date(m.updatedAt).toLocaleString(language==='si'?'si-LK':'en-GB'))}</p></div>`}</section></div><aside class="card stack"><h3>${t('Keep your match','ඔබේ තරගය සුරකින්න')}</h3><p class="muted">${t('Download a JSON backup containing the rules, deliveries and correction history. You can restore it on another device.','නීති, පන්දු සහ correction history ඇතුළත් JSON backup එක ලබාගන්න. වෙනත් උපාංගයක නැවත ලබාගත හැක.')}</p>${button(t('Export backup','Backup ලබාගන්න'),'export','primary','download')}<p class="small muted">${t('This URL is local to your workspace. It is not a public live-score link.','මෙම URL එක ඔබේ වැඩබිමට පමණයි. පොදු live-score link එකක් නොවේ.')}</p></aside></div>`}
function future(page){const player=page==='players';return `<div class="page-head"><div><span class="eyebrow">${t('COMING TO YOUR WORKSPACE','ඉදිරියේදී ඔබේ වැඩබිමට')}</span><h1>${player?t('Every player. One story.','සෑම ක්‍රීඩකයෙකුටම එක ඉතිහාසයක්.'):t('Bring your tournament together.','ඔබේ තරගාවලිය එක තැනකට.')}</h1></div></div><section class="card stack"><span class="badge neutral">${t('Not available in this build','මෙම build එකේ තවම නැහැ')}</span><h2>${player?t('Profiles that follow the player','ක්‍රීඩකයා සමඟ යන වාර්තා'):t('From the group stage to the final','කාණ්ඩ වටයේ සිට අවසන් තරගයට')}</h2><p class="muted">${player?t('Verified player profiles, separate softball and hardball career stats, and team history are planned for Release 1. This build keeps player figures within each match.','තහවුරු කළ profiles, වෙනම softball/hardball stats සහ team history Release 1 සඳහා සැලසුම් කර ඇත. දැනට එක් එක් තරගයේ දත්ත සුරැකේ.'):t('League, knockout and group-to-knockout formats are planned for Release 1. The current build supports standalone matches only.','League, knockout සහ groups → knockout Release 1 සඳහා සැලසුම් කර ඇත. දැනට standalone matches පමණයි.')}</p><a href="#new" class="btn primary">${t('Start a standalone match','තනි තරගයක් අරඹන්න')}${icon('arrow')}</a></section>`}
function render(){try{const {page,id}=route();let content;if(page==='home'||page==='account')content=home();else if(page==='new')content=newMatch();else if(page==='matches')content=`<div class="page-head"><div><span class="eyebrow">${t('YOUR MATCHBOOK','ඔබේ තරග පොත')}</span><h1>${t('Matches','තරග')}</h1></div><div class="row">${button(t('Restore backup','Backup නැවත ලබාගන්න'),'import','','download')}<a class="btn primary" href="#new">${icon('plus')}${t('New match','අලුත් තරගයක්')}</a></div></div><div class="home-grid"><section>${matches.length?matches.map(matchCard).join(''):`<div class="card empty"><h3>${t('No matches yet','තවම තරග නැහැ')}</h3><a class="btn primary" href="#new">${t('Create your first match','පළමු තරගය සකසන්න')}</a></div>`}</section><aside class="notice">${icon('shield')}<span>${t('Matches are saved in this browser. Export backups to keep a separate copy.','තරග මෙම browser එකේ save වේ. වෙනම පිටපතක් සඳහා backup ලබාගන්න.')}</span></aside></div>`;else if(['score','live'].includes(page)){const m=matches.find(m=>m.id===id);content=m?(page==='score'?scoring(m):live(m)):`<div class="card empty"><h2>${t('Match not found on this device','තරගය මෙම උපාංගයේ නැහැ')}</h2><a class="btn" href="#matches">${t('Back to matches','තරග වෙත')}</a></div>`}else content=future(page);app.innerHTML=shell(content);wireForm()}catch(e){app.innerHTML=shell(`<div class="notice warning">${esc(e.message)}</div>`)} }
function showDialog(title,body){modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button('×','close','ghost')}</div>${body}`;modal.showModal();modal.querySelector('input,select')?.focus()}
function eventId(){return crypto.randomUUID()}
async function commit(event){if(busy)return;const m=current();if(!m)return;busy=true;try{const next=event==='undo'?undo(m):append(m,{...event,id:eventId(),at:new Date().toISOString()});await saveMatch(next,m.revision);matches=matches.map(x=>x.id===next.id?next:x);modal.close();render();toast(t('Saved on this device','මෙම උපාංගයේ සුරැකුණා'))}catch(e){const err=modal.open?modal.querySelector('.form-error'):null;if(err)err.textContent=e.message;else toast(e.message);if(e.message.includes('another tab')){matches=await listMatches();render()}}finally{busy=false}}
function wireForm(){const form=document.querySelector('#match-form');if(!form)return;form.addEventListener('input',()=>{['A','B'].forEach(key=>{form.elements.battingFirst.querySelector(`option[value="${key}"]`).textContent=form.elements['team'+key].value||'Team '+key})});form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const f=Object.fromEntries(new FormData(form)),settings=validateSettings({...f,freeHit:!!f.freeHit,wideCounts:!!f.wideCounts,noBallCounts:!!f.noBallCounts});const now=new Date().toISOString();let m={id:eventId(),schemaVersion:1,settings,events:[],revision:0,audit:[],createdAt:now,updatedAt:now};m=append(m,{type:'start',striker:f.striker,nonStriker:f.nonStriker,bowler:f.bowler,id:eventId(),at:now});await saveMatch(m,null);matches.unshift(m);link('score/'+m.id)}catch(e){form.querySelector('.form-error').textContent=e.message}finally{busy=false}}}
function playerDialog(kind){const m=current(),st=replay(m);if(kind==='second'){showDialog(t('Second innings','දෙවන ඉනිම'),`<form id="player-form"><p class="muted">${esc(team(m.settings,st.current.team==='A'?'B':'A'))} · ${t('Target','ඉලක්කය')} ${st.current.total+1}</p>${field(t('Striker','පිතිකරු'),'striker')}${field(t('Non-striker','අනෙක් පිතිකරු'),'nonStriker')}${field(t('Opening bowler','පන්දු යවන්නා'),'bowler')}<p class="form-error" role="alert"></p><button class="btn primary">${t('Start innings','ඉනිම අරඹන්න')}</button></form>`)}else{const bowlers=kind==='bowler'?Object.keys(st.current.bowlers).filter(n=>n!==st.current.bowler):[];showDialog(kind==='batter'?t('Next batter','ඊළඟ පිතිකරු'):t('Next bowler','ඊළඟ පන්දු යවන්නා'),`<form id="player-form">${field(t('Player name','ක්‍රීඩකයාගේ නම'),'name','','text','list="known-players"')}<datalist id="known-players">${bowlers.map(n=>`<option value="${esc(n)}">`).join('')}</datalist><p class="form-error" role="alert"></p><button class="btn primary">${t('Continue scoring','ඉදිරියට')}</button></form>`)}modal.querySelector('form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));commit({type:kind==='second'?'start':kind,...f})}}
function deliveryDialog(wicket=false){const m=current(),i=replay(m).current;showDialog(wicket?t('Record a wicket','කඩුල්ල සටහන් කරන්න'):t('Record extras','අතිරේක සටහන් කරන්න'),`<form id="delivery-form">${wicket?`<label class="field">${t('Dismissal','දැවී යාම')}<select name="wicket">${[['bowled','Bowled','පන්දුව කඩුල්ලේ'],['caught','Caught','උඩපන්දුව'],['lbw','LBW','කඩුල්ල මුවා කිරීම'],['stumped','Stumped','ස්ටම්ප් කිරීම'],['hitWicket','Hit wicket','කඩුල්ලට පහර දීම'],['runOut','Run out','දුවද්දී දැවී යාම']].filter(([key])=>!i.freeHit||key==='runOut').map(([v,en,si])=>`<option value="${v}">${t(en,si)}</option>`).join('')}</select></label>`:''}<label class="field">${t('Delivery type','පන්දු වර්ගය')}<select name="kind">${(wicket?[['normal','Fair delivery','සාමාන්‍ය පන්දුව'],['wide','Wide','වයිඩ්'],['noBall','No-ball','නිපන්දුව']]:[['wide','Wide','වයිඩ්'],['noBall','No-ball','නිපන්දුව'],['bye','Bye','බයි'],['legBye','Leg bye','ලෙග් බයි']]).map(([v,en,si])=>`<option value="${v}">${t(en,si)}</option>`).join('')}</select></label>${field(t('Additional runs (excluding penalty)','දඬුවම් ලකුණු හැර අමතර ලකුණු'),'runs',0,'number','min="0" max="6"')}<label class="field" id="credit-field">${t('No-ball additional runs credited to','නිපන්දුවේ අමතර ලකුණු')}<select name="credit"><option value="bat">${t('Batter','පිතිකරු')}</option><option value="bye">${t('Byes','බයි')}</option><option value="legBye">${t('Leg byes','ලෙග් බයි')}</option></select></label>${!wicket?`<label class="check"><input type="checkbox" name="boundary">${t('Boundary (no completed running)','Boundary (දිවූ ලකුණු නොවේ)')}</label>`:`<div id="runout-fields" class="stack"><label class="field">${t('Dismissed batter (before delivery)','දැවී ගිය පිතිකරු (පන්දුවට පෙර)')}<select name="out"><option value="striker">${esc(i.striker)}</option><option value="nonStriker">${esc(i.nonStriker)}</option></select></label><label class="field">${t('Replacement end before over-end swap','ඕවර අවසාන මාරුවට පෙර නව පිතිකරුගේ අන්තය')}<select name="nextEnd"><option value="striker">${t('Facing the next delivery','ඊළඟ පන්දුවට මුහුණ දෙයි')}</option><option value="nonStriker">${t('Non-striker’s end','අනෙක් අන්තය')}</option></select></label></div>`}<p class="small muted">${t('Enter completed runs only. The configured wide/no-ball penalty is added automatically. Overthrows and uncommon dismissals are not yet supported.','නිම කළ ලකුණු පමණක් දාන්න. Wide/no-ball දඬුවම ස්වයංක්‍රීයව එකතු වේ. Overthrows සහ විශේෂ දැවී යාම් තවම නැහැ.')}</p><p class="form-error" role="alert"></p><button class="btn primary">${t('Save delivery','පන්දුව සුරකින්න')}</button></form>`);const form=modal.querySelector('form');const update=()=>{modal.querySelector('#credit-field').hidden=form.elements.kind.value!=='noBall';if(wicket)modal.querySelector('#runout-fields').hidden=form.elements.wicket.value!=='runOut'};form.onchange=update;update();form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));commit({type:'ball',kind:f.kind,runs:+f.runs,running:f.boundary?0:+f.runs,boundary:!!f.boundary,credit:f.credit,...(wicket?{wicket:f.wicket,out:f.out,nextEnd:f.nextEnd}:{})})}}
function exportMatch(){const m=current();if(!m)return;const blob=new Blob([JSON.stringify(m,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`cricavo-${m.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Backup downloaded','Backup ලබාගත්තා'))}
function importMatch(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2_000_000)throw Error('Backup exceeds 2 MB');const raw=JSON.parse(await file.text());if(raw.schemaVersion!==1||!Array.isArray(raw.events)||raw.events.length>10000)throw Error('Unsupported backup');replay(raw);const now=new Date().toISOString(),m={id:eventId(),schemaVersion:1,settings:validateSettings(raw.settings),events:raw.events,revision:1,audit:Array.isArray(raw.audit)?raw.audit:[],createdAt:now,updatedAt:now,restored:true};await saveMatch(m,null);matches.unshift(m);link('score/'+m.id);toast(t('Backup restored as a new match','Backup නව තරගයක් ලෙස ලබාගත්තා'))}catch(e){toast(e.message)}};input.click()}
async function demo(){if(busy)return;busy=true;try{const now=new Date().toISOString();let m={id:eventId(),schemaVersion:1,demo:true,settings:validateSettings({teamA:'Colombo Kings',teamB:'Galle Strikers',overs:6,ballsPerOver:6,players:8,ballType:'softball',widePenalty:1,noBallPenalty:1,battingFirst:'A',freeHit:true}),events:[],revision:0,audit:[],createdAt:now,updatedAt:now};m=append(m,{type:'start',striker:'N. Perera',nonStriker:'K. Silva',bowler:'A. Fernando',id:eventId()});for(const n of [0,4,1,2,6])m=append(m,{type:'ball',kind:'normal',runs:n,running:n>=4?0:n,boundary:n>=4,id:eventId()});await saveMatch(m,null);matches.unshift(m);link('score/'+m.id)}catch(e){toast(e.message)}finally{busy=false}}
async function action(a){if(a==='close'){modal.close();return}if(a==='language'){language=language==='en'?'si':'en';try{localStorage.setItem('cricavo-language',language)}catch{}render();return}if(a==='theme'){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('cricavo-theme',theme)}catch{}render();return}if(a==='demo')return demo();if(a==='account'){await accountUI.show();return}if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null}else showDialog(t('Install Cricavo','Cricavo ස්ථාපනය'),`<div class="stack"><p>${t('Android: open the browser menu and choose Install app or Add to Home screen.','Android: browser menu එකෙන් Install app හෝ Add to Home screen තෝරන්න.')}</p><p>${t('iPhone: open in Safari, tap Share, then Add to Home Screen.','iPhone: Safari හි Share → Add to Home Screen තෝරන්න.')}</p><p class="muted small">${t('Open the app online once before using it offline. Browser support varies.','Offline භාවිතයට පෙර එක් වරක් online විවෘත කරන්න. Browser අනුව පහසුකම් වෙනස් වේ.')}</p></div>`);return}if(a==='import')return importMatch();if(a==='export')return exportMatch();if(a.startsWith('tab-')){tab=a.slice(4);render();return}if(a.startsWith('innings-')){selectedInnings=+a.slice(8);render();return}if(a==='undo'){showDialog(t('Undo last action?','අවසාන ක්‍රියාව ආපසු ගන්නද?'),`<div class="stack"><p>${t('The last delivery or player selection will be removed from the score and retained in the audit history.','අවසාන පන්දුව හෝ ක්‍රීඩක තේරීම ආපසු ගෙන audit history එකේ තබයි.')}</p><p class="form-error" role="alert"></p>${button(t('Undo action','ආපසු ගන්න'),'confirm-undo','danger')}</div>`);return}if(a==='confirm-undo')return commit('undo');if(['batter','bowler','second'].includes(a))return playerDialog(a);if(a==='extras'||a==='wicket')return deliveryDialog(a==='wicket');if(a.startsWith('run-')){const n=+a.slice(4);return commit({type:'ball',kind:'normal',runs:n,running:n>=4?0:n,boundary:n>=4})}}
const accountUI=createAccountUI({modal,t,escape:esc,toast});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action).catch(err=>toast(err.message))});
window.addEventListener('hashchange',()=>{selectedInnings=null;render();window.scrollTo(0,0)});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('focus',async()=>{if(!busy){try{matches=await listMatches();if(!modal.open&&route().page!=='new')render()}catch{}}});
app.innerHTML=shell(`<div class="loading">${t('Opening your matchbook…','ඔබේ තරග පොත විවෘත වෙමින්…')}</div>`);
try{matches=await listMatches();render()}catch(e){app.innerHTML=shell(`<div class="notice warning">${t('Device storage is unavailable. Enable browser storage before scoring.','Device storage භාවිත කළ නොහැක. Scoring කිරීමට browser storage සක්‍රිය කරන්න.')} ${esc(e.message)}</div>`)}
if(location.hash==='#account') accountUI.show();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast(t('Offline app installation failed. Keep this page open and retry online.','Offline app සැකසුම අසාර්ථකයි. Online විට නැවත උත්සාහ කරන්න.')));
